/* Iron Tide Army Builder V0.5.3 — local-first, sans serveur. */
'use strict';
const $=id=>document.getElementById(id), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>Math.random().toString(36).slice(2,11),money=n=>Number.isFinite(n)?`${Math.round(n*100)/100} pts`:'prix indisponible';
const DB=JSON.parse($('catalogue-data').textContent),B=JSON.parse($('baremes-data').textContent),DOC=JSON.parse($('doctrines-data').textContent);
// Captures : matériel d'origine courant uniquement, sous réserve de période/front.
DB.push({id:'universal-motos',nation:'Allemagne',name:'Motos (transport universel)',kind:'transport',subtype:'Motos',traction:'roues',size:'TP',speed:'Très rapide',armor:'Non blindé',traits:'Transport (1)',costs:{Early:5,Mid:5,Late:5},source:'Transport universel · Groupe 3',sourceRow:0,universal:true});const originals=DB.slice();for(const x of originals){if(x.rarity||!['armor','gun','transport'].includes(x.kind))continue;for(const nation of ['Allemagne','URSS']){if(nation===x.nation)continue;DB.push({...x,id:'capture-'+nation+'-'+x.id,nation,originNation:x.nation,captured:true,name:x.name+' (capturé '+x.nation+')',rarity:x.kind==='gun'?1:0,source:x.source+' · capture'});}}
const KINDS={reserve:'Infanterie de Réserve',scout:'Section d’éclaireurs',horseScout:'Éclaireurs à cheval',sniper:'Section de snipers URSS',inf:'Infanterie',cav:'Cavalerie',genie:'Génie',recon:'Reconnaissance',light:'Chars légers',medium:'Chars moyens',heavy:'Chars lourds',assault:'Canons d’assaut',td:'Chasseurs de chars',at:'Antichar',art:'Artillerie rapprochée',aa:'Antiaérien',air:'Support aérien',transport:'Transports / soutien',fort:'Fortifications'};
const PERIOD=['Early','Mid','Late'],EXPS=['Novice','Vétéran','Élite','As'],MORALES=['Hésitant','Vaillant','Tenace'];
let state={name:'Ma force Iron Tide',front:'EST',period:'Late',year:1944,season:'',budget:2000,fortBudget:300,independentForts:[],corps:[{id:id(),nation:'Allemagne',group:'standard',doctrine:0,formations:[]}] ,custom:[]};
let view='army',search='',editId=null;
const CATALOG_INDEX=new Map(DB.map(x=>[x.id,x]));
const all=()=>DB.concat(state.custom),item=key=>CATALOG_INDEX.get(key)||state.custom.find(x=>x.id===key),corps=key=>state.corps.find(x=>x.id===key),formation=key=>state.corps.flatMap(c=>c.formations).find(f=>f.id===key);
const opts=(arr,val)=>arr.map(x=>{let [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${E(v)}" ${String(v)===String(val)?'selected':''}>${E(label)}</option>`}).join('');
const sel=(key,arr,val,extra='')=>`<select data-action="${key}" ${extra}>${opts(arr,val)}</select>`;
const field=(name,action,value,typ='text',extra='')=>`<label>${name}<input data-action="${action}" type="${typ}" value="${E(value)}" ${extra}></label>`;
const chk=(label,act,checked,extra='')=>`<label class="check"><input type="checkbox" data-action="${act}" ${checked?'checked':''} ${extra}>${label}</label>`;
const mkUnit=()=>({id:id(),type:'Ligne',command:false,exp:null,morale:null,osc:false,fan:false,as:false,options:[],transportId:''});
const mkFormation=(kind,corpId)=>({id:id(),corpId,kind,name:KINDS[kind],exp:'Vétéran',morale:'Vaillant',osc:false,fan:false,units:[],structure:kind==='reserve'?'reserve':['scout','horseScout'].includes(kind)?'scout':kind==='sniper'?'sniper':'standard',size:'standard',infType:'Ligne',engineer:false,reinforceEngineer:false,sections:[],hq:mkUnit(),reserveUnits:[],scoutSource:'',scoutType:'Ligne',scoutCount:3,sniperCount:2,sniperHQ:'Réserve',models:[],support:[],obs:false,command:false,forts:[]});
const isInf=f=>['inf','cav','genie','reserve','scout','horseScout','sniper'].includes(f.kind),isGun=f=>['at','art','aa'].includes(f.kind),isArmor=f=>['light','medium','heavy','assault','td'].includes(f.kind);
const isEligibleAs=f=>isArmor(f)||isGun(f)||f.kind==='air';
// Toutes les formations ont un coût structurel nul : seules les unités, options et supports sont facturés.
function baseFormation(f){return 0}
function adjust(base,exp,morale,osc,fan){if(base==null)return null;let tier=base<=100?0:base<=200?1:2;return base+(B.experience[exp==='Entraîné'?'Vétéran':exp]?.[tier]||0)+(B.morale[morale]||0)+(osc?B.morale.Oscillant:0)+(fan?B.morale.Fanatique:0)}
function unitPrice(f,u){let table=['cav','horseScout'].includes(f.kind)?B.cav:B.inf,extra=['cav','horseScout'].includes(f.kind)?B.cavOptions:B.infOptions;let n=(table[u.type]||0)+(u.command?(table.Commandement||0):0);for(let opt of u.options)n+=extra[opt]||0;let tr=item(u.transportId);if(tr){let p=tr.costs[state.period];if(p==null)return null;n+=p}return adjust(n,u.exp||f.exp,u.morale||f.morale,u.osc||f.osc,u.fan||f.fan)}
function canAdaptTracks(x){return /^(chenill[eé]|semi[- ]?chenill[eé])/i.test(String(x?.traction||'').trim())}
// Restrictions nationales et catégories, appliquées aussi aux anciennes sauvegardes.
function zimmeritEligible(x){
 if(!x||x.nation!=='Allemagne'||x.kind!=='armor')return false;
 const role=String(x.armorRole||'').toLowerCase();
 const desc=[x.name,x.subtype,x.type].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const front=Number(String(x.armor||'').match(/\d+/)?.[0]||0);
 const engineer=/genie|pionier|pioneer|bergepanzer|raumpanzer|minenraum|bruckenleger|brueckenleger|bruckenleger|flammpanzer|flam(m)?|dozer/.test(desc);
 const assault=role==='assault'||/canon d.assaut|sturmgeschutz|sturmpanzer/.test(desc);
 const heavyTD=/jagdtiger|jagdpanther|ferdinand|elefant|chasseur de chars lourd/.test(desc)||(role==='td'&&front>=17);
 return role==='medium'||role==='heavy'||engineer||assault||heavyTD;
}
const VEHICLE_EQUIPMENT={
 light:['MG antiaérienne','HMG antiaérienne','Plateforme radio'],
 medium:['Schürzen','Optique IR','MG antiaérienne','HMG antiaérienne','Plateforme radio'],
 heavy:['Schürzen','Optique IR','MG antiaérienne','HMG antiaérienne','Plateforme radio'],
 assault:['Schürzen','Optique IR','MG antiaérienne','HMG antiaérienne'],
 td:['Télémètre','Schürzen','Optique IR','MG antiaérienne','HMG antiaérienne'],
 selfpropelled:['Télémètre','MG antiaérienne','HMG antiaérienne'],
 transport:['MG antiaérienne','HMG antiaérienne','Transport de munitions','Plateforme radio','Plateforme de réparation','Équipement génie'],
 engineer:['Équipement génie','Lames Rhino','Lame bulldozer','Roll Miner','Masses Crab','2 traverses','Pont','Fascine']
};
function vehicleCategory(x){if(x?.id==='universal-motos')return 'motos';if(x?.kind==='transport')return 'transport';let role=String(x?.armorRole||'').toLowerCase();let name=String(x?.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(/genie|pionier|pioneer|bergepanzer|raumpanzer|minenraum|bruckenleger|brueckenleger|crab|dozer/.test(name))return 'engineer';if(x?.kind==='gun'&&x?.mounting!=='tracté')return 'selfpropelled';return VEHICLE_EQUIPMENT[role]?role:null}
function isExtraAllowed(x,k){let cat=vehicleCategory(x);if(cat==='motos')return false;if(k==='Zimmerit')return true;if(/chenilles adaptées/i.test(k))return state.front==='EST'&&canAdaptTracks(x);if(!cat)return true;return VEHICLE_EQUIPMENT[cat].some(v=>normEquipment(v)===normEquipment(k))}
function engineerCargoPrice(m,x){if(!(m.options||[]).includes('Équipement génie')||!allowedVehicleOption(x,'Équipement génie'))return 0;const qty=(v,max)=>Math.max(0,Math.min(max,Math.trunc(Number(v)||0)));return qty(m.engineerPanzerfaust,3)*(B.infOptions['Panzerfaust']||0)+qty(m.engineerCharges,2)*(B.infOptions['Charge explosive']||B.infOptions['Charges explosives']||0)}
function panzerfaustCount(f){let units=[f.hq,...(f.reserveUnits||[]),...(f.sections||[]).flatMap(x=>x.units),...(f.engineerSection?.units||[])];return units.reduce((n,u)=>n+(u?.options||[]).filter(k=>/panzerfaust/i.test(k)).length,0)}
function panzerfaustLimit(f){return Number.isFinite(f.panzerfaustLimit)?f.panzerfaustLimit:3}
function allowedVehicleOption(x,k){
 const key=normEquipment(k);
 if(key==='optique ir')return x?.nation==='Allemagne';
 if(key==='stabilisateur')return x?.nation==='USA';
 if(key==='zimmerit')return state.year>=1943&&zimmeritEligible(x);if(!isExtraAllowed(x,k))return false;
 return true;
}
function allowedDraftOption(k){
 const key=normEquipment(k);
 if(key==='optique ir')return draft.nation==='Allemagne';
 if(key==='stabilisateur')return draft.nation==='USA';
 if(key==='zimmerit')return state.year>=1943&&draft.kind==='armor'&&draft.nation==='Allemagne'&&(!draft.sourceId||zimmeritEligible(item(draft.sourceId)));
 return true;
}
function modelPrice(f,m){let x=item(m.catalogId);if(!x)return null;let base=m.customPrice!=null?Number(m.customPrice):x.costs?.[state.period];if(base==null||!Number.isFinite(base))return null;let extras=(m.options||[]).reduce((n,k)=>n+(!allowedVehicleOption(x,k)||equipmentIncluded(x,k)?0:(k==='Zimmerit'?2:(B.vehicleOptions[k]??B.gunOptions[k]??0))),0);if(m.chenilles&&state.front==='EST'&&canAdaptTracks(x))extras+=B.vehicleOptions['Chenilles adaptées']||5;if(x.id==='universal-motos')extras+=({standard:3,mmg:5,hmg:7}[m.sidecar]||0);extras+=engineerCargoPrice(m,x);let p=adjust(base+extras,m.exp||f.exp,m.morale||f.morale,m.osc??f.osc,m.fan??f.fan);if(m.escort&&escortAllowed(f)){let ep=escortPrice(f,m);if(ep!=null)p+=ep}if(m.tractorId){let t=item(m.tractorId);if(t){if(t.costs[state.period]==null)return null;p+=t.costs[state.period]}}return p}
function formationPrice(f){let n=baseFormation(f);if(isInf(f))return infantryFormationPrice(f);for(let u of f.units){let p=unitPrice(f,u);if(p==null)return null;n+=p}for(let m of f.models){let p=modelPrice(f,m);if(p==null)return null;n+=p}for(let s of f.support)n+=B.support[s]||0;if(f.obs)n+=B.support['Observateur supplémentaire']||15;for(let k of f.forts)n+=B.fortifications[k]||0;return n}
function rareOf(x){if(!x)return 0;let r=x.rarity||0;if(x.obsolete)r=Math.max(r,2);return r}
function rarity(f){return Math.max(0,...f.models.map(m=>rareOf(item(m.catalogId))))}
function frontOk(x){let t=(x.theater||'').toUpperCase();if(!t)return true;let keywords={EST:['EST','RUSS','SOVI','FINLAND','FINLAN','POLOG'],OUEST:['OUEST','FRANCE','NORMAND','ARDENN','BELGI'],AFRIQUE:['AFRI','TUNIS','LIBY','EGYP'],ITALIE:['ITAL','SICIL'],FINLANDE:['FINLAN','EST']}[state.front]||[];return keywords.some(k=>t.includes(k))}
function available(x,c){if(x.nation!==c.nation&&!x.universal)return false;if(x.costs?.[state.period]==null)return false;if(!frontOk(x))return false;return true}
function candidates(f){let c=corps(f.corpId);return all().filter(x=>available(x,c)).filter(x=>{if(isInf(f))return x.kind==='transport'||x.kind==='gun'||x.kind==='armor';if(f.kind==='recon')return x.kind!=='air'&&Boolean(x.recon);if(f.kind==='light'||f.kind==='medium'||f.kind==='heavy')return x.kind==='armor'&&x.armorRole===f.kind;if(f.kind==='assault'||f.kind==='td')return x.kind==='armor'&&x.armorRole===f.kind;if(isGun(f))return x.kind==='gun'&&x.roleKey===f.kind;if(f.kind==='air')return x.kind==='air';if(f.kind==='transport')return x.kind==='transport';return false})}
function limits(f){let sov=corps(f.corpId)?.nation==='URSS';if(['light','medium','assault','td'].includes(f.kind))return sov?[2,10]:[2,5];if(f.kind==='heavy')return sov?[2,5]:[1,3];if(isGun(f)){let first=f.models[0]&&item(f.models[0].catalogId);let weight=first?.weight||'moyen',mount=first?.mounting||'tracté';return weight==='lourd'?[1,3]:mount!=='tracté'?[2,4]:weight==='léger'?[2,6]:[2,4]}return null}
function parseLimit(s){if(!s)return [0,Infinity];if(s.endsWith('+'))return [Number(s.slice(0,-1)),Infinity];if(s.includes('-'))return s.split('-').map(Number);return [Number(s),Number(s)]}
function warnings(){let a=[],forms=state.corps.flatMap(c=>c.formations);let rares=forms.filter(f=>rarity(f)>0);if(rares.length>3)a.push(`Rareté : ${rares.length} formations rares (maximum 3).`);if(rares.filter(f=>rarity(f)>=2).length>2)a.push('Plus de 2 formations très rares ** ou prototypes.');if(rares.filter(f=>rarity(f)>=3).length>1)a.push('Plus d’une formation prototype ***.');let grand=0;for(let c of state.corps){let total=0;let counts={};for(let f of c.formations){counts[f.kind]=(counts[f.kind]||0)+1;if(f.kind==='cav')counts.light=(counts.light||0)+1;let p=formationPrice(f);if(p==null)a.push(`${f.name} : budget manquant dans l’OdB.`);else total+=p;let l=limits(f);if(l&&f.models.length&&(f.models.length<l[0]||f.models.length>l[1]))a.push(`${f.name} : ${f.models.length} pièce(s), limites indicatives ${l[0]}–${l[1]}.`);if(isInf(f)&&panzerfaustCount(f)>panzerfaustLimit(f))a.push(`${f.name} : ${panzerfaustCount(f)} Panzerfaust (maximum ${panzerfaustLimit(f)}).`);if(f.kind==='sniper'&&c.nation!=='URSS')a.push('Section de snipers : URSS uniquement.');if(f.kind==='recon'&&f.models.some(m=>{const x=item(m.catalogId);return !x?.recon||x.kind==='air'}))a.push(`${f.name} : unité incompatible avec la reconnaissance terrestre (avions à placer en support aérien).`)}let d=DOC[c.doctrine]||DOC[0];for(let [k,v] of Object.entries(d.limits)){let [min,max]=parseLimit(v),n=counts[k]||0;if(n<min||n>max)a.push(`${c.nation} / ${d.name} : ${KINDS[k]||k} ${n}, requis ${v}.`)}if(c===state.corps[0])grand=total;else if(total>state.budget/2)a.push('Le corps auxiliaire dépasse 50 % du budget total.')}if(state.corps.length>1&&grand<state.budget/2)a.push('Le corps principal est inférieur à 50 % du budget de référence.');let total=forms.reduce((n,f)=>n+(formationPrice(f)||0),0);if(total>state.budget)a.push(`Budget dépassé de ${money(total-state.budget)}.`);return a}
function summary(){let forms=state.corps.flatMap(c=>c.formations),cost=forms.reduce((n,f)=>n+(formationPrice(f)||0),0),fort=state.independentForts.reduce((n,k)=>n+(B.fortifications[k]||0),0),rare=forms.filter(f=>rarity(f));return `<div class="stats"><div><small>Armée</small><b>${money(cost)} / ${money(state.budget)}</b></div><div><small>Formations</small><b>${forms.length}</b></div><div><small>Rareté</small><b>${rare.length}/3 · ** ${rare.filter(f=>rarity(f)>=2).length}/2 · *** ${rare.filter(f=>rarity(f)>=3).length}/1</b></div><div><small>Fortifications indépendantes</small><b>${money(fort)} / ${money(state.fortBudget)}</b></div></div>`}
function header(){return `<header><div><h1>IRON TIDE <span>ARMY BUILDER</span></h1><p>V0.5.2 · Groupe 3 · Allemagne / URSS · données OdB V9 · budget actualisé</p></div><nav><button data-action="tab" data-value="army" class="${view==='army'?'active':''}">Armée</button><button data-action="tab" data-value="workshop" class="${view==='workshop'?'active':''}">Calculateur universel</button><button data-action="tab" data-value="fort" class="${view==='fort'?'active':''}">Fortifications</button></nav></header>`}
function army(){for(let c of state.corps)for(let f of c.formations){if(isInf(f))normalizeFormation(f);if(['scout','horseScout'].includes(f.kind)){let src=scoutSources(f).find(x=>x.id===f.scoutSource)||scoutSources(f)[0];if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale}}}return `<section class="panel"><h2>Paramètres de bataille</h2><div class="grid">${field('Nom de la liste','listName',state.name)}<label>Front${sel('front',['EST','OUEST','AFRIQUE','ITALIE','FINLANDE'],state.front)}</label><label>Période${sel('period',PERIOD,state.period)}</label>${field('Année','year',state.year,'number','min="1939" max="1950"')}<label>Saison${sel('season',['','Printemps','Été','Automne','Hiver'].map(x=>[x,x||'Non précisée']),state.season)}</label>${field('Budget global (pts)','budget',state.budget,'number','min="1"')}</div></section>${summary()}<section class="panel"><div class="line"><h2>Corps d’armée</h2>${state.corps.length<2?'<button data-action="addCorps">+ Corps auxiliaire</button>':''}</div>${state.corps.map((c,i)=>corpMarkup(c,i)).join('')}</section><section class="panel"><h2>Contrôles de composition</h2>${warnings().length?warnings().map(x=>`<p class="warning">⚠ ${E(x)}</p>`).join(''):'<p class="good">Aucun avertissement détecté. Les exceptions des OdB Word restent à intégrer.</p>'}</section>${saveMarkup()}`}
function corpMarkup(c,i){let d=DOC[c.doctrine]||DOC[0],p=c.formations.reduce((n,f)=>n+(formationPrice(f)||0),0);return `<article class="corp"><div class="line"><h3>${i===0?'Corps principal':'Corps auxiliaire'} <span class="pill">${money(p)}</span></h3>${i?`<button class="danger" data-action="removeCorps" data-c="${c.id}">Retirer</button>`:''}</div><div class="grid"><label>Nation${sel('nation',['Allemagne','URSS'],c.nation,`data-c="${c.id}"`)}</label><label>Groupe d’armées${sel('group',[['standard','Groupe standard (provisoire)'],['reserve','Groupe de Réserve (provisoire)']],c.group,`data-c="${c.id}"`)}</label><label>Structure / doctrine${sel('doctrine',DOC.map((x,j)=>[j,x.name]),c.doctrine,`data-c="${c.id}"`)}</label></div><p class="muted">${E(d.note==='-'?'':d.note)} · Limites : ${Object.entries(d.limits).map(([k,v])=>`${KINDS[k]||k} ${v}`).join(' · ')}</p><div class="toolbar"><label>Ajouter une formation ${sel('newKind',Object.entries(KINDS).filter(([k])=>k!=='fort'&&(k!=='sniper'||c.nation==='URSS')).map(([k,v])=>[k,v]),c.nextKind||'inf',`data-c="${c.id}"`)}</label><button data-action="addFormation" data-c="${c.id}">+ Ajouter</button></div>${c.formations.map(f=>formationMarkup(f)).join('')}</article>`}
function formationMarkup(f){let inf=isInf(f),choices=candidates(f),lim=limits(f),rare=rarity(f);return `<article class="formation"><div class="line"><h3>${E(f.name)} <span class="pill">${money(formationPrice(f))}</span>${rare?` <span class="rare">${'*'.repeat(rare)}</span>`:''}</h3><button class="danger small" data-action="removeFormation" data-f="${f.id}">Supprimer</button></div><div class="grid">${field('Nom de formation','formationName',f.name,'text',`data-f="${f.id}"`)}<label>Expérience${sel('formationExp',EXPS.filter(x=>x!=='As'||isEligibleAs(f)),f.exp,`data-f="${f.id}"`)}</label><label>Moral${sel('formationMorale',MORALES,f.morale,`data-f="${f.id}"`)}</label>${chk('Oscillant','formationOsc',f.osc,`data-f="${f.id}"`)}${chk('Fanatique','formationFan',f.fan,`data-f="${f.id}"`)}</div><p class="muted">Valeurs héritées par chaque unité, sauf exception individuelle. ${lim?`Effectif de référence : ${lim[0]}–${lim[1]}.`:''}</p>${inf?`<p class="muted">Panzerfaust : ${panzerfaustCount(f)} / ${panzerfaustLimit(f)} (hors exceptions OdB)</p>`:''}${inf?infMarkupV4(f):modelListMarkup(f,choices)}${inf?'':supportMarkup(f)}${f.forts.length?`<p>Fortifications intégrées : ${f.forts.map(E).join(', ')}</p>`:''}</article>`}

// Groupe 3 — unités structurées, QG, sections, renforts et transports.
const INF_TYPES=['Servants / équipe légère','Milice','Réserve','Ligne','Lourde','Assaut','PM / automatiques','Commissaire politique'];
const ENGINEER_RE=/charge explosive|mine magn[eé]tique|goliath|borgward|lance-flammes/i;
const mkSection=(type='Ligne',genie=false)=>({id:id(),type,genie,units:Array.from({length:3},()=>({...mkUnit(),type})),support:[],transportId:'',sidecar:''});
function initializeFormation(f){if(f.kind==='reserve'){f.reserveUnits=Array.from({length:4},()=>({...mkUnit(),type:'Réserve'}));f.infType='Réserve'}else if(['scout','horseScout'].includes(f.kind)){f.sections=[mkSection('Ligne')];if(f.kind==='horseScout')f.sections[0].units.pop()}else if(f.kind==='sniper'){f.sniperCount=2}else if(['inf','cav','genie'].includes(f.kind)){f.sections=Array.from({length:3},()=>mkSection('Ligne',f.kind==='genie'));f.engineer=f.kind==='genie'}f.hq={...mkUnit(),type:f.infType,command:true};}
function normalizeFormation(f){if(!isInf(f))return;if(!f.hq)f.hq={...mkUnit(),type:f.infType||'Ligne',command:true};if(!f.infType)f.infType=f.kind==='reserve'?'Réserve':'Ligne';if(!Array.isArray(f.sections))f.sections=[];if(!Array.isArray(f.reserveUnits))f.reserveUnits=[];if(f.kind==='reserve'&&!f.reserveUnits.length)f.reserveUnits=Array.from({length:4},()=>({...mkUnit(),type:f.infType}));if(['inf','cav','genie'].includes(f.kind)&&!f.sections.length){f.sections=Array.from({length:3},()=>mkSection(f.infType,f.kind==='genie'));if(f.units?.length){f.sections[0].units=f.units.map(u=>({...u,options:u.options||[]})).slice(0,4);f.units=[]}}if(['scout','horseScout'].includes(f.kind)&&!f.sections.length){f.sections=[mkSection(f.infType)];if(f.kind==='horseScout')f.sections[0].units.pop();}if(f.kind==='sniper'&&!f.sniperCount)f.sniperCount=2;}
function infTable(f){return ['cav','horseScout'].includes(f.kind)?B.cav:B.inf}
function infOptTable(f){return ['cav','horseScout'].includes(f.kind)?B.cavOptions:B.infOptions}
function infCost(f,u,command=false){const t=infTable(f),o=infOptTable(f);let n=(t[u.type]||0)+(command?(t.Commandement||0):0);for(let k of (u.options||[])){if((!ENGINEER_RE.test(k)||u.genie||f.engineer||f.kind==='genie')&&k!=='Reco'&&k!=='Indépendantes')n+=o[k]||0}return adjust(n,u.exp||f.exp,u.morale||f.morale,u.osc||f.osc,u.fan||f.fan)}
function transportPrice(tid,sidecar=''){if(!tid)return 0;let x=item(tid);if(!x)return null;let p=x.costs?.[state.period];if(p==null)return null;return p+(x.id==='universal-motos'?({standard:3,mmg:5,hmg:7}[sidecar]||0):0)}
function infantryFormationPrice(f){normalizeFormation(f);if(['scout','horseScout'].includes(f.kind)){let src=scoutSources(f).find(x=>x.id===f.scoutSource)||scoutSources(f)[0];if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale;f.sections[0].type=src.infType;for(let u of f.sections[0].units){u.type=src.infType;u.exp=null;u.morale=null}}}let n=baseFormation(f);if(f.kind==='reserve'){
 n+=infCost(f,f.hq,true);for(let u of f.reserveUnits)n+=infCost(f,u);if(f.reinforceEngineer){{let sp=sectionPrice(f,f.engineerSection||mkSection('Ligne',true));if(sp==null)return null;n+=sp}}}
 else if(f.kind==='sniper'){let hq={...f.hq,type:f.sniperHQ==='Sniper'?'Servants / équipe légère':f.sniperHQ};n+=infCost(f,hq,true);if(f.sniperHQ==='Sniper')n+=B.support.Sniper||0;n+=(f.sniperCount||2)*(B.support.Sniper||0)}
 else{if(!['scout','horseScout'].includes(f.kind))n+=infCost(f,f.hq,true);for(let sec of f.sections){let sp=sectionPrice(f,sec);if(sp==null)return null;n+=sp}}
 const hqTr=['scout','horseScout','sniper'].includes(f.kind)?0:transportPrice(f.hq.transportId,f.hq.sidecar);if(hqTr==null)return null;n+=hqTr;
 for(let m of f.models){let p=modelPrice(f,m);if(p==null)return null;n+=p}
 for(let k of f.support||[])n+=B.support[k]||0;
 return n;
}
function sectionPrice(f,sec){let n=0;for(let u of sec.units){n+=infCost(f,{...u,genie:sec.genie||f.engineer})}let tr=transportPrice(sec.transportId,sec.sidecar);if(tr==null)return null;n+=tr;for(let k of sec.support||[])n+=B.support[k]||0;return n}
function escortAllowed(f){const nation=corps(f.corpId)?.nation;if(nation==='URSS')return state.year>=1941&&['light','medium','heavy','assault','td'].includes(f.kind);return nation==='Allemagne'&&state.year>=1943&&state.front==='EST'&&['medium','heavy','assault'].includes(f.kind)}
function escortPrice(f,m){let n=m.escort==='pm'?10:m.escort==='assault'?15:0;if(!n)return 0;for(let k of m.escortOptions||[]){if(k!=='Reco'&&k!=='Indépendantes'&&!ENGINEER_RE.test(k))n+=B.infOptions[k]||0}return adjust(n,m.escortExp||f.exp,m.escortMorale||f.morale,false,false)}
function escortMarkup(f,m){if(!escortAllowed(f))return '';let sov=corps(f.corpId)?.nation==='URSS',v=m.escort||'';return `<details><summary>${sov?'Tankodesantniki':'Escorte de char'} ${v?'— '+money(escortPrice(f,m)):''}</summary><div class="grid"><label>Unité rattachée${sel('escortType',sov?[['','Aucune'],['pm','PM · 10 pts']]:[['','Aucune'],['pm','PM · 10 pts'],['assault','Assaut · 15 pts']],v,`data-f="${f.id}" data-m="${m.id}"`)}</label>${v?`<label>Expérience${sel('escortExp',EXPS.filter(x=>x!=='As'),m.escortExp||f.exp,`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Moral${sel('escortMorale',MORALES,m.escortMorale||f.morale,`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}</div>${v?`<div class="options">${Object.entries(B.infOptions).filter(([k])=>!['Reco','Indépendantes'].includes(k)&&!ENGINEER_RE.test(k)).map(([k,p])=>chk(`${E(k)} (+${money(p)})`,'escortOption',(m.escortOptions||[]).includes(k),`data-f="${f.id}" data-m="${m.id}" data-value="${E(k)}"`)).join('')}</div><p class="muted">Commandement assuré par la formation blindée · ni Indépendant ni Reco · 1 unité par char.</p>`:''}</details>`}
function sectionSupportMarkup(f,sec){return `<details><summary>Supports de section (${(sec.support||[]).length})</summary><div class="options">${Object.entries(B.support).filter(([k])=>k!=='Observateur supplémentaire'&&(!ENGINEER_RE.test(k)||sec.genie||f.engineer)).map(([k,p])=>chk(`${E(k)} (${money(p)})`,'sectionSupport',(sec.support||[]).includes(k),`data-f="${f.id}" data-sec="${sec.id}" data-value="${E(k)}"`)).join('')}</div></details>`}
function transportSelector(f,action,tid,sidecar,extra){let list=all().filter(x=>x.kind==='transport'&&available(x,corps(f.corpId)));return `<div class="grid"><label>Transport${sel(action,[['','Sans transport'],...list.map(x=>[x.id,`${x.name} · ${money(x.costs[state.period])}`])],tid||'',extra)}</label>${tid==='universal-motos'?`<label>Side-car${sel(action+'Sidecar',[['','Aucun'],['standard','Standard (+3) Transport (1) + ST'],['mmg','MMG (+5)'],['hmg','HMG (+7)']],sidecar||'',extra)}</label>`:''}</div>`}
function infantryUnitMarkup(f,u,sec){let table=infTable(f),extras=infOptTable(f),eng=!!(f.engineer||sec?.genie);return `<div class="unit"><div class="line"><label>Type${sel('g3UnitType',Object.keys(table).filter(k=>k!=='Commandement'),u.type,`data-f="${f.id}" data-u="${u.id}"`)}</label><b>${money(infCost(f,{...u,genie:eng}))}</b></div><div class="grid"><label>Expérience${sel('g3UnitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],u.exp||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Moral${sel('g3UnitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],u.morale||'',`data-f="${f.id}" data-u="${u.id}"`)}</label></div><details><summary>Équipements d'infanterie</summary><div class="options">${Object.entries(extras).filter(([k])=>!['Reco','Indépendantes'].includes(k)&&(!ENGINEER_RE.test(k)||eng)&&(!/goliath|borgward/i.test(k)||corps(f.corpId)?.nation==='Allemagne')).map(([k,p])=>chk(`${E(k)} (${money(p)})`,'g3UnitOption',(u.options||[]).includes(k),`data-f="${f.id}" data-u="${u.id}" data-value="${E(k)}" ${/panzerfaust/i.test(k)&&panzerfaustCount(f)>=panzerfaustLimit(f)&&!(u.options||[]).includes(k)?'disabled':''}`)).join('')}</div></details></div>`}
function sectionMarkup(f,sec,i){return `<div class="unit"><div class="line"><h4>Section ${i+1} — ${E(sec.type)}</h4><b>${money(sectionPrice(f,sec))}</b></div><div class="grid">${['scout','horseScout'].includes(f.kind)?`<span>Type lié : ${E(f.infType)}</span>`:`<label>Type de la section${sel('sectionType',Object.keys(infTable(f)).filter(k=>k!=='Commandement'),sec.type,`data-f="${f.id}" data-sec="${sec.id}"`)}</label>`}${['scout','horseScout'].includes(f.kind)?'':!f.engineer?chk('Section Génie','sectionEngineer',sec.genie,`data-f="${f.id}" data-sec="${sec.id}" ${!sec.genie&&f.sections.some(x=>x.genie)?'disabled':''}`):'<span>Compagnie Génie</span>'}</div>${sec.units.map(u=>infantryUnitMarkup(f,u,sec)).join('')}${sec.units.length<4?`<button class="small" data-action="sectionAddUnit" data-f="${f.id}" data-sec="${sec.id}">+ Unité</button>`:''}${sec.units.length>(f.kind==='horseScout'?2:3)?`<button class="small danger" data-action="sectionRemoveUnit" data-f="${f.id}" data-sec="${sec.id}">Retirer une unité</button>`:''}${sectionSupportMarkup(f,sec)}${transportSelector(f,'sectionTransport',sec.transportId,sec.sidecar,`data-f="${f.id}" data-sec="${sec.id}"`)}</div>`}
function scoutSources(f){return corps(f.corpId).formations.filter(g=>g.id!==f.id&&(f.kind==='horseScout'?g.kind==='cav':['inf','genie','reserve'].includes(g.kind)))}
function infMarkupV4(f){normalizeFormation(f);let isReserve=f.kind==='reserve',isScout=['scout','horseScout'].includes(f.kind),isSniper=f.kind==='sniper',sources=isScout?scoutSources(f):[];if(isScout){let src=sources.find(x=>x.id===f.scoutSource)||sources[0];if(src){f.scoutSource=src.id;f.infType=src.infType;f.exp=src.exp;f.morale=src.morale}if(f.sections.length!==1)f.sections=[f.sections[0]||mkSection(f.infType)];f.sections[0].type=f.infType;for(let u of f.sections[0].units){u.type=f.infType;u.exp=null;u.morale=null}}
 let top=isSniper?`<h4>Section de snipers soviétiques</h4><div class="grid"><label>QG${sel('sniperHQ',[['Réserve','Réserve'],['Ligne','Ligne'],['PM / automatiques','PM'],['Sniper','Support Sniper']],f.sniperHQ||'Réserve',`data-f="${f.id}"`)}</label><label>Supports Sniper${sel('sniperCount',[[2,'2 supports indépendants'],[3,'3 supports indépendants']],f.sniperCount||2,`data-f="${f.id}"`)}</label></div><label>Expérience QG${sel('g3UnitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],f.hq.exp||'',`data-f="${f.id}" data-u="${f.hq.id}"`)}</label><label>Moral QG${sel('g3UnitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],f.hq.morale||'',`data-f="${f.id}" data-u="${f.hq.id}"`)}</label><p class="muted">Tous les supports Sniper sont indépendants, sans radio.</p>`:isScout?`<h4>${f.kind==='horseScout'?'Section d’éclaireurs à cheval (2 à 4 unités)':'Section d’éclaireurs à pied (3 à 4 unités)'}</h4>${sources.length?`<label>Formation de référence${sel('scoutSource',sources.map(x=>[x.id,`${x.name} · ${x.infType} · ${x.exp} · ${x.morale}`]),f.scoutSource,`data-f="${f.id}"`)}</label><p class="muted">Type, expérience et moral synchronisés avec la compagnie.</p>`:`<label>Type de section${sel('infType',Object.keys(infTable(f)).filter(k=>k!=='Commandement'),f.infType,`data-f="${f.id}"`)}</label>`}`:isReserve?`<h4>Groupe de Réserve : QG + 4 à 8 unités</h4><div class="grid"><label>Type initial${sel('infType',INF_TYPES,f.infType,`data-f="${f.id}"`)}</label>${chk('Renfort Génie (section de 3 à 4 unités)','reinforceEngineer',f.reinforceEngineer,`data-f="${f.id}"`)}</div>`:`<div class="grid"><label>Structure${sel('companySize',[['reduite','Réduite · 2 sections'],['standard','Standard · 3 sections'],['augmentee','Augmentée · 4 sections']],f.size||'standard',`data-f="${f.id}"`)}</label><label>Type initial${sel('infType',INF_TYPES,f.infType,`data-f="${f.id}"`)}</label>${chk('Compagnie entière de Génie','companyEngineer',f.engineer,`data-f="${f.id}"`)}</div>`;
 let hq=isSniper||isScout?'':`<div class="unit"><h4>QG de compagnie</h4>${infantryUnitMarkup(f,f.hq)}${transportSelector(f,'hqTransport',f.hq.transportId,f.hq.sidecar,`data-f="${f.id}"`)}<details><summary>Supports rattachés au QG</summary><div class="options">${Object.entries(B.support).map(([k,p])=>chk(`${E(k)} (${money(p)})`,'support',(f.support||[]).includes(k),`data-f="${f.id}" data-value="${E(k)}"`)).join('')}</div></details></div>`;
 let body=isSniper?'':isReserve?`<div class="subhead"><b>Groupe de Réserve (${f.reserveUnits.length}/8)</b>${f.reserveUnits.length<8?`<button class="small" data-action="reserveAdd" data-f="${f.id}">+ Unité</button>`:''}</div>${f.reserveUnits.map(u=>`<div>${infantryUnitMarkup(f,u)}${f.reserveUnits.length>4?`<button class="small danger" data-action="reserveRemove" data-f="${f.id}" data-u="${u.id}">Retirer</button>`:''}</div>`).join('')}${f.reinforceEngineer?sectionMarkup(f,f.engineerSection||(f.engineerSection=mkSection('Ligne',true)),0):''}`:f.sections.map((sec,i)=>sectionMarkup(f,sec,i)).join('');
 return `<div class="unit">${top}</div>${hq}${body}${!isSniper?modelListMarkup(f,candidates(f)):''}`;
}
function findInfUnit(f,uid){return [f.hq,...(f.reserveUnits||[]),...(f.sections||[]).flatMap(s=>s.units),...(f.engineerSection?.units||[])].find(x=>x?.id===uid)}
function findSection(f,sid){return [...(f.sections||[]),f.engineerSection].find(x=>x?.id===sid)}
function infMarkup(f){let table=['cav','horseScout'].includes(f.kind)?B.cav:B.inf,options=['cav','horseScout'].includes(f.kind)?B.cavOptions:B.infOptions;return `<div class="subhead"><b>Unités d’infanterie / cavalerie</b><button class="small" data-action="addUnit" data-f="${f.id}">+ Unité</button></div>${f.units.map(u=>`<div class="unit"><div class="line"><label>Type${sel('unitType',Object.keys(table).filter(k=>!k.toLowerCase().includes('commandement')),u.type,`data-f="${f.id}" data-u="${u.id}"`)}</label><b>${money(unitPrice(f,u))}</b><button class="danger small" data-action="removeUnit" data-f="${f.id}" data-u="${u.id}">Retirer</button></div><div class="grid">${chk('Commandement (+ supplément)','unitCommand',u.command,`data-f="${f.id}" data-u="${u.id}"`)}<label>Expérience${sel('unitExp',[['','Formation'],...EXPS.filter(x=>x!=='As').map(x=>[x,x])],u.exp||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Moral${sel('unitMorale',[['','Formation'],...MORALES.map(x=>[x,x])],u.morale||'',`data-f="${f.id}" data-u="${u.id}"`)}</label><label>Transport facultatif${sel('unitTransport',[['','Sans transport'],...all().filter(x=>x.kind==='transport'&&available(x,corps(f.corpId))).map(x=>[x.id,x.name])],u.transportId||'',`data-f="${f.id}" data-u="${u.id}"`)}</label></div><details><summary>Équipements et compétences</summary><div class="options">${Object.entries(options).filter(([k])=>f.kind==='genie'||!/charge explosive|mine magnétique|goliath|borgward/i.test(k)).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'unitOption',u.options.includes(k),`data-f="${f.id}" data-u="${u.id}" data-value="${E(k)}"`)).join('')}</div></details></div>`).join('')}${modelListMarkup(f,candidates(f))}`}
function modelListMarkup(f,choices){let shown=choices.filter(x=>!search||x.name.toLowerCase().includes(search.toLowerCase())).slice(0,350);return `<div class="subhead"><b>${isInf(f)?'Appuis attachés':'Pièces et véhicules'} (${f.models.length})</b></div>${f.models.map(m=>modelMarkup(f,m)).join('')}<div class="toolbar"><label>Filtre catalogue <input data-action="search" placeholder="Rechercher…" value="${E(search)}"></label><label>Choisir un modèle${sel('catalogChoice',shown.map(x=>[x.id,`${x.name} · ${x.mounting||x.subtype} · ${money(x.costs[state.period])}`]),f.choice||shown[0]?.id||'',`data-f="${f.id}"`)}</label><button data-action="addModel" data-f="${f.id}" ${!shown.length?'disabled':''}>+ Recruter</button></div>${isGun(f)?'<p class="muted">Canon tracté, porté ou automoteur : catégories conservées depuis les OdB. Les tracteurs ne sont proposés qu’aux canons tractés.</p>':''}`}
// Équipements de série : cases cochées et verrouillées, déjà payées dans le prix OdB.
// La colonne « équipement additionnel » est une indication, pas une option de série certaine.
function normEquipment(t){return String(t||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b1\s*x\s*(mg|hmg)\b/g,'$1').replace(/co[ -]?axiale/g,'coaxiale').replace(/anti[ -]?aerienne/g,'antiaerienne').replace(/fumigenes?/g,'fumigene').replace(/\breco\b/g,'reconnaissance').replace(/\bcoduite double\b|\bconduite double\b/g,'double conduite').replace(/\bpivot\b/g,'pivot').replace(/\bfirecrackers+s?\b/g,'firecracker').replace(/[^a-z0-9+]+/g,' ').trim()}
function equipmentIncluded(x,k){
 // Inspect each separated trait rather than searching the entire string: 'Sans radio'
 // must not activate 'Radio', and 'Sans fumigènes' must not activate smoke launchers.
 const raw=[x.constant,x.traits].filter(v=>v&&v!=='-').join(' ; ');
 const tokens=raw.split(/[;,/]/).map(normEquipment).filter(Boolean);
 const key=normEquipment(k).replace(/^\s*(?:mg|hmg)\s+/,'$&');
 const aliases={
  'lance fumigene':['fumigene','lance fumigene'],
  'reconnaissance':['reconnaissance'],
  'mg coaxiale':['mg coaxiale'], 'mg caisse':['mg caisse'],
  'mg antiaerienne':['mg aa','mg antiaerienne'], 'mg tourelle':['mg tourelle'],
  'hmg coaxiale':['hmg coaxiale'], 'hmg caisse':['hmg caisse'],
  'hmg antiaerienne':['hmg aa','hmg antiaerienne'], 'hmg tourelle':['hmg tourelle'],
  'equipement genie':['equipement de genie','equipement genie'],
  'double conduite':['double conduite'], 'pivot 360':['pivot 360'],
  'plateforme tir':['plateforme de tir','plateforme tir'],
  'optiques mediocres':['mauvaises optiques','mauvaise optique','optiques mediocres'],
  'tir rapide':['cadence tir rapide','tir rapide'],
  'optique ir':['optique ir','viseur ir']
 };
 const keys=aliases[key]||[key];
 return tokens.some(token=>{
   // A negated capability cannot imply a positive one.
   if(/^sans\s/.test(token) && key!=='sans radio')return false;
   if(key==='sans radio')return /^sans\s+radio$/.test(token);
   return keys.some(a=>a&&new RegExp('(?:^|\\s)'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:$|\\s|\\()').test(token));
 });
}
function modelOptionMarkup(x,m,availableOpts,f){
 return Object.entries(availableOpts).filter(([k])=>!/chenilles adaptées/i.test(k)&&allowedVehicleOption(x,k)&&(!/^\/\s*(?:MG|HMG) antia/i.test(k)||!Object.keys(availableOpts).some(a=>a===k.replace(/^\/\s*/,'')))).map(([k,v])=>{
   const included=equipmentIncluded(x,k);
   const checked=included||m.options.includes(k);
   return chk(`${E(k)} (${included?'de série · inclus':money(v)})`,'modelOption',checked,`data-f="${f.id}" data-m="${m.id}" data-value="${E(k)}" ${included?'disabled title="Équipement ou trait de série, déjà inclus dans le prix OdB"':''}`);
 }).join('');
}
function modelMarkup(f,m){let x=item(m.catalogId);if(!x)return `<p class="warning">Référence manquante : ${E(m.catalogId)}</p>`;let tract=x.kind==='gun'&&x.mounting==='tracté',tractors=all().filter(y=>y.kind==='transport'&&y.tractorClass&&available(y,corps(f.corpId))&&(!x.weight||y.tractorClass===x.weight||y.tractorClass==='lourd'));let availableOpts=isGun(f)?B.gunOptions:B.vehicleOptions;return `<div class="unit"><div class="line"><div><b>${E(x.name)}</b> ${x.rarity?' <span class="rare">'+('*'.repeat(x.rarity))+'</span>':''}<p class="muted">${E(x.subtype)} · ${E(x.mounting)} · ${E(x.weapon)} · ${E(x.armor)} · ${E(x.source)} ligne ${x.sourceRow}</p><p class="muted">Inclus dans le coût OdB : ${E(x.constant||'—')} · Traits : ${E(x.traits||'—')} · Équipement additionnel indiqué : ${E(x.additional||'—')}</p></div><b>${money(modelPrice(f,m))}</b><button class="danger small" data-action="removeModel" data-f="${f.id}" data-m="${m.id}">Retirer</button></div><div class="grid"><label>Expérience${sel('modelExp',[['','Formation'],...EXPS.filter(x=>x!=='As'||isEligibleAs(f)).map(x=>[x,x])],m.exp||'',`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Moral${sel('modelMorale',[['','Formation'],...MORALES.map(x=>[x,x])],m.morale||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>${tract?`<label>Tracteur compatible${sel('tractor',[['','Aucun'],...tractors.map(y=>[y.id,y.name])],m.tractorId||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}${state.front==='EST'&&canAdaptTracks(x)?chk('Chenilles adaptées','chenilles',m.chenilles,`data-f="${f.id}" data-m="${m.id}"`):''}</div><details><summary>Équipements de série cochés (inclus) et options supplémentaires</summary><div class="options">${modelOptionMarkup(x,m,availableOpts,f)}</div></details>${x.id==='universal-motos'?`<label>Side-car${sel('sidecar',[['','Sans side-car'],['standard','Standard +3 pts · Transport (1) + ST'],['mmg','MMG +5 pts'],['hmg','HMG +7 pts']],m.sidecar||'',`data-f="${f.id}" data-m="${m.id}"`)}</label>`:''}${(m.options||[]).includes('Équipement génie')?`<div class="unit"><b>Équipement de Génie — Firecracker (4+)</b><p class="muted">Explosifs transportés, non utilisables comme armement du véhicule. Aucun réapprovisionnement.</p><div class="grid"><label>Panzerfaust emportés${sel('engineerPanzerfaust',[[0,'0'],[1,'1'],[2,'2'],[3,'3']],m.engineerPanzerfaust||0,`data-f="${f.id}" data-m="${m.id}"`)}</label><label>Charges explosives emportées${sel('engineerCharges',[[0,'0'],[1,'1'],[2,'2']],m.engineerCharges||0,`data-f="${f.id}" data-m="${m.id}"`)}</label></div></div>`:''}${(m.options||[]).includes('Transport de munitions')?'<p class="muted">Transport de munitions : réapprovisionne les munitions épuisées et le carburant des lance-flammes ; ne donne pas Firecracker.</p>':''}${escortMarkup(f,m)}</div>`}
function supportMarkup(f){return `<details><summary>OBS, commandement et supports</summary><div class="options">${isGun(f)?chk('Observateur (OBS)','obs',f.obs,`data-f="${f.id}"`)+chk('Unité de commandement (incluse dans la base de formation)','command',f.command,`data-f="${f.id}"`):''}${Object.entries(B.support).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'support',f.support.includes(k),`data-f="${f.id}" data-value="${E(k)}"`)).join('')}</div>${DOC[corps(f.corpId).doctrine]?.fortifications?`<div class="toolbar"><label>Fortification selon doctrine${sel('fortChoice',Object.keys(B.fortifications),f.fortChoice||Object.keys(B.fortifications)[0],`data-f="${f.id}"`)}</label><button data-action="addFortFormation" data-f="${f.id}">+ Ajouter</button></div>`:''}</details>`}
function saveMarkup(){return `<section class="panel"><h2>Sauvegarder / partager</h2><div class="toolbar"><button data-action="save">Sauvegarder localement</button><button data-action="export">Exporter JSON</button><label class="filebutton">Importer JSON<input id="import" type="file" accept=".json,application/json"></label><button data-action="print">Imprimer / PDF</button><button data-action="reset" class="danger">Nouvelle liste</button></div><p class="muted">Données OdB V9 ; aucun coût manquant n’est inventé. Les groupes d’armées et exceptions des OdB Word devront être renseignés depuis les documents Word non fournis.</p></section>`}
function forts(){let total=state.independentForts.reduce((n,k)=>n+(B.fortifications[k]||0),0);return `<section class="panel"><h2>Fortifications indépendantes</h2><p>Cette liste est distincte du budget global et ne nécessite pas de doctrine.</p><div class="grid">${field('Budget dédié','fortBudget',state.fortBudget,'number','min="0"')}<label>Fortification${sel('indFortChoice',Object.entries(B.fortifications).map(([k,v])=>[k,`${k} · ${money(v)}`]),state.fortChoice||Object.keys(B.fortifications)[0])}</label></div><button data-action="addIndFort">+ Ajouter</button><h3>Total : ${money(total)} / ${money(state.fortBudget)}</h3>${state.independentForts.map((x,i)=>`<div class="line unit"><span>${E(x)} — ${money(B.fortifications[x])}</span><button class="small danger" data-action="removeIndFort" data-index="${i}">Retirer</button></div>`).join('')}${saveMarkup()}</section>`}
let draft={kind:'inf',name:'Nouvelle unité',nation:'Allemagne',base:15,exp:'Vétéran',morale:'Vaillant',osc:false,fan:false,as:false,options:[],sourceId:''};
function workshopPrice(){let n=Number(draft.base);if(!Number.isFinite(n))return null;for(let k of draft.options.filter(k=>allowedDraftOption(k)))n+= (B.infOptions[k]??B.cavOptions[k]??B.vehicleOptions[k]??B.gunOptions[k]??0);return adjust(n,draft.exp,draft.morale,draft.osc,draft.fan)}
function workshop(){let options=draft.kind==='inf'?B.infOptions:draft.kind==='cav'?B.cavOptions:draft.kind==='gun'?B.gunOptions:B.vehicleOptions;let sources=all().filter(x=>x.nation===draft.nation&&((draft.kind==='gun'&&x.kind==='gun')||(draft.kind==='armor'&&x.kind==='armor')||(draft.kind==='transport'&&x.kind==='transport')||(draft.kind==='air'&&x.kind==='air')));return `<section class="panel"><h2>Calculateur universel</h2><p>Barèmes fixes du budget actualisé. Le blindage des véhicules existants est conservé : aucun éditeur de blindage. Les créations sont enregistrées comme copies personnelles.</p><div class="grid"><label>Catégorie${sel('draftKind',[['inf','Infanterie'],['cav','Cavalerie'],['armor','Véhicule blindé'],['gun','Canon / artillerie / AA'],['transport','Transport'],['air','Aviation'],['fort','Fortification'],['support','Support']],draft.kind)}</label><label>Nation${sel('draftNation',['Allemagne','URSS'],draft.nation)}</label>${field('Nom','draftName',draft.name)}<label>Charger une unité existante${sel('draftSource',[['','Nouvelle unité'],...sources.map(x=>[x.id,x.name])],draft.sourceId)}</label>${field('Coût de base officiel ou OdB (pts)','draftBase',draft.base,'number','step="0.01"')}<label>Expérience${sel('draftExp',EXPS.filter(x=>x!=='As'||['armor','gun','air'].includes(draft.kind)),draft.exp)}</label><label>Moral${sel('draftMorale',MORALES,draft.morale)}</label>${chk('Oscillant','draftOsc',draft.osc)}${chk('Fanatique','draftFan',draft.fan)}</div><details><summary>Traits et équipements (${draft.options.length})</summary><div class="options">${Object.entries(options).filter(([k])=>allowedDraftOption(k)).map(([k,v])=>chk(`${E(k)} (${money(v)})`,'draftOption',draft.options.includes(k),`data-value="${E(k)}"`)).join('')}</div></details><div class="stats"><div><small>Prix recalculé</small><b>${money(workshopPrice())}</b></div><div><small>Coût de base</small><b>${money(Number(draft.base))}</b></div></div><div class="toolbar"><button data-action="draftSave">Enregistrer dans ma bibliothèque</button><button data-action="draftReset">Nouvelle fiche</button></div><p class="muted">Le calculateur applique les suppléments d’expérience par tranche (0–100 / 101–200 / plus de 200) et le moral du budget. Les caractéristiques techniques des matériels créés doivent être renseignées dans leurs fiches de référence ; les prix ne sont pas extrapolés automatiquement.</p><h3>Bibliothèque personnalisée (${state.custom.length})</h3>${state.custom.map(x=>`<div class="line unit"><span>${E(x.name)} · ${E(x.nation)} · ${money(x.costs?.[state.period])}</span><button data-action="deleteCustom" data-id="${x.id}" class="small danger">Supprimer</button></div>`).join('')}</section>${saveMarkup()}`}
function render(){const expanded=[...document.querySelectorAll('#app details')].map((el,i)=>el.open?i:-1).filter(i=>i>=0);document.title='Iron Tide — Army Builder V0.5.1';$('app').innerHTML=header()+`<main>${view==='army'?army():view==='workshop'?workshop():forts()}</main>`;const details=document.querySelectorAll('#app details');for(const i of expanded)if(details[i])details[i].open=true;}
function download(name,content,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function update(e){let el=e.target,a=el.dataset.action;if(!a)return;let f=formation(el.dataset.f),c=corps(el.dataset.c),u=f?.units.find(x=>x.id===el.dataset.u),m=f?.models.find(x=>x.id===el.dataset.m),v=el.type==='checkbox'?el.checked:el.value,choice=el.dataset.value;
 if(a==='listName')state.name=v;else if(['front','period','season'].includes(a))state[a]=v;else if(['year','budget','fortBudget'].includes(a))state[a]=Number(v);
 else if(a==='nation'){c.nation=v;c.formations=[]}else if(a==='group')c.group=v;else if(a==='doctrine')c.doctrine=Number(v);
 else if(a==='newKind')c.nextKind=v;else if(a==='formationName')f.name=v;else if(a==='formationExp')f.exp=v;else if(a==='formationMorale')f.morale=v;else if(a==='formationOsc')f.osc=v;else if(a==='formationFan')f.fan=v;
 else if(a==='unitType')u.type=v;else if(a==='unitCommand')u.command=v;else if(a==='unitExp')u.exp=v||null;else if(a==='unitMorale')u.morale=v||null;else if(a==='unitTransport')u.transportId=v;else if(a==='unitOption')u.options=v?[...new Set([...u.options,choice])]:u.options.filter(x=>x!==choice);
 else if(a==='catalogChoice')f.choice=v;else if(a==='modelExp')m.exp=v||null;else if(a==='modelMorale')m.morale=v||null;else if(a==='tractor')m.tractorId=v;else if(a==='chenilles')m.chenilles=v;else if(a==='modelOption'){if(allowedVehicleOption(item(m.catalogId),choice)&&!equipmentIncluded(item(m.catalogId),choice))m.options=v?[...new Set([...m.options,choice])]:m.options.filter(x=>x!==choice);}
 else if(a==='obs')f.obs=v;else if(a==='command')f.command=v;else if(a==='support')f.support=v?[...new Set([...f.support,choice])]:f.support.filter(x=>x!==choice);else if(a==='fortChoice')f.fortChoice=v;else if(a==='indFortChoice')state.fortChoice=v;
 else if(a==='companySize'){f.size=v;let count={reduite:2,standard:3,augmentee:4}[v]||3;while(f.sections.length<count)f.sections.push(mkSection(f.infType,f.engineer));f.sections=f.sections.slice(0,count)}
 else if(a==='infType'){f.infType=v;if(f.kind==='reserve'){f.reserveUnits.forEach(u=>u.type=v)}else if(['scout','horseScout'].includes(f.kind)){f.sections[0].type=v;f.sections[0].units.forEach(u=>u.type=v)}else{f.sections.forEach(sec=>{sec.type=v;sec.units.forEach(u=>u.type=v)})}}
 else if(a==='companyEngineer'){f.engineer=v;if(v)f.sections.forEach(sec=>sec.genie=true);else f.sections.forEach(sec=>sec.genie=false)}
 else if(a==='sectionType'){let sec=findSection(f,el.dataset.sec);sec.type=v;sec.units.forEach(u=>u.type=v)}
 else if(a==='sectionEngineer'){let sec=findSection(f,el.dataset.sec);if(v&&f.sections.some(x=>x!==sec&&x.genie)&&!f.engineer)return;sec.genie=v}
 else if(a==='reinforceEngineer'){f.reinforceEngineer=v;if(v&&!f.engineerSection)f.engineerSection=mkSection('Ligne',true)}
 else if(a==='scoutSource'){f.scoutSource=v}
 else if(a==='sniperHQ')f.sniperHQ=v;else if(a==='sniperCount')f.sniperCount=Number(v);
 else if(['g3UnitType','g3UnitExp','g3UnitMorale','g3UnitOption'].includes(a)){let uu=findInfUnit(f,el.dataset.u);if(uu){if(a==='g3UnitType')uu.type=v;else if(a==='g3UnitExp')uu.exp=v||null;else if(a==='g3UnitMorale')uu.morale=v||null;else if(!v||!/panzerfaust/i.test(choice)||panzerfaustCount(f)<panzerfaustLimit(f)||((uu.options||[]).includes(choice)))uu.options=v?[...new Set([...(uu.options||[]),choice])]:(uu.options||[]).filter(k=>k!==choice)}}
 else if(a==='sectionSupport'){let sec=findSection(f,el.dataset.sec);sec.support=v?[...new Set([...(sec.support||[]),choice])]:(sec.support||[]).filter(k=>k!==choice)}
 else if(a==='hqTransport')f.hq.transportId=v;else if(a==='hqTransportSidecar')f.hq.sidecar=v;
 else if(a==='sectionTransport')findSection(f,el.dataset.sec).transportId=v;else if(a==='sectionTransportSidecar')findSection(f,el.dataset.sec).sidecar=v;
 else if(a==='escortType')m.escort=v;else if(a==='escortExp')m.escortExp=v;else if(a==='escortMorale')m.escortMorale=v;else if(a==='escortOption')m.escortOptions=v?[...new Set([...(m.escortOptions||[]),choice])]:(m.escortOptions||[]).filter(k=>k!==choice);
 else if(a==='sidecar')m.sidecar=v;else if(a==='engineerPanzerfaust')m.engineerPanzerfaust=Math.max(0,Math.min(3,Number(v)));else if(a==='engineerCharges')m.engineerCharges=Math.max(0,Math.min(2,Number(v)));
 else if(a==='search'){search=v;}else if(a.startsWith('draft')){let key={draftKind:'kind',draftNation:'nation',draftName:'name',draftBase:'base',draftExp:'exp',draftMorale:'morale',draftOsc:'osc',draftFan:'fan',draftSource:'sourceId'}[a];if(a==='draftOption')draft.options=allowedDraftOption(choice)&&v?[...new Set([...draft.options,choice])]:draft.options.filter(x=>x!==choice);else if(a==='draftSource'){draft.sourceId=v;let x=item(v);if(x){draft.name=x.name+' — variante';draft.base=x.costs[state.period]??x.baseCost??0;draft.kind=x.kind==='gun'?'gun':x.kind==='air'?'air':x.kind==='transport'?'transport':'armor';draft.options=[]}}else if(key)draft[key]=v;}
 render();}
function click(e){let el=e.target.closest('button[data-action]');if(!el)return;let a=el.dataset.action,f=formation(el.dataset.f),c=corps(el.dataset.c);if(a==='tab'){view=el.dataset.value;search='';render();return}
 if(a==='addCorps')state.corps.push({id:id(),nation:'URSS',group:'standard',doctrine:0,formations:[]});else if(a==='removeCorps')state.corps=state.corps.filter(x=>x.id!==c.id);
 else if(a==='addFormation'){let kind=c.nextKind||'inf';let nf=mkFormation(kind,c.id);initializeFormation(nf);c.formations.push(nf)}else if(a==='removeFormation'){let owner=corps(f.corpId);owner.formations=owner.formations.filter(x=>x.id!==f.id)}
 else if(a==='sectionAddUnit'){let sec=findSection(f,el.dataset.sec);if(sec.units.length<4)sec.units.push({...mkUnit(),type:sec.type})}
 else if(a==='sectionRemoveUnit'){let sec=findSection(f,el.dataset.sec);if(sec.units.length>(f.kind==='horseScout'?2:3))sec.units.pop()}
 else if(a==='reserveAdd'){if(f.reserveUnits.length<8)f.reserveUnits.push({...mkUnit(),type:f.infType})}
 else if(a==='reserveRemove'){if(f.reserveUnits.length>4)f.reserveUnits=f.reserveUnits.filter(u=>u.id!==el.dataset.u)}
 else if(a==='addUnit')f.units.push(mkUnit());else if(a==='removeUnit')f.units=f.units.filter(x=>x.id!==el.dataset.u);
 else if(a==='addModel'){let choices=candidates(f).filter(x=>!search||x.name.toLowerCase().includes(search.toLowerCase()));let x=item(f.choice||choices[0]?.id);if(x&&choices.some(y=>y.id===x.id))f.models.push({id:id(),catalogId:x.id,exp:null,morale:null,options:[],chenilles:false,tractorId:'',escort:'',escortExp:null,escortMorale:null,escortOptions:[],sidecar:''})}
 else if(a==='removeModel')f.models=f.models.filter(x=>x.id!==el.dataset.m);else if(a==='addFortFormation')f.forts.push(f.fortChoice||Object.keys(B.fortifications)[0]);else if(a==='addIndFort')state.independentForts.push(state.fortChoice||Object.keys(B.fortifications)[0]);else if(a==='removeIndFort')state.independentForts.splice(Number(el.dataset.index),1);
 else if(a==='draftReset')draft={kind:'inf',name:'Nouvelle unité',nation:'Allemagne',base:15,exp:'Vétéran',morale:'Vaillant',osc:false,fan:false,options:[],sourceId:''};
 else if(a==='draftSave'){let p=workshopPrice();if(p==null)return alert('Prix invalide');let orig=item(draft.sourceId);let x={...(orig||{}),id:'custom-'+id(),name:draft.name||'Nouvelle unité',nation:draft.nation,kind:orig?.kind||(draft.kind==='gun'?'gun':draft.kind==='air'?'air':draft.kind==='transport'?'transport':draft.kind==='armor'?'armor':'support'),type:orig?.type||draft.kind,subtype:orig?.subtype||draft.kind,armor:orig?.armor||'',weapon:orig?.weapon||'',rarity:orig?.rarity||0,roleKey:orig?.roleKey||'art',armorRole:orig?.armorRole||'other',mounting:orig?.mounting||'tracté',costs:{Early:p,Mid:p,Late:p},custom:true,source:'Bibliothèque personnelle',sourceRow:0};state.custom.push(x);alert('Fiche ajoutée à la bibliothèque personnelle. Son prix est fixe pour les trois périodes jusqu’à modification.')}
 else if(a==='deleteCustom')state.custom=state.custom.filter(x=>x.id!==el.dataset.id);
 else if(a==='save'){localStorage.setItem('iron-tide-v03',JSON.stringify(state));alert('Liste sauvegardée dans ce navigateur.')}
 else if(a==='export')download('Iron_Tide_liste_V0.5.1.json',JSON.stringify({version:'0.5.1',state},null,2),'application/json');else if(a==='print')window.print();else if(a==='reset'){if(confirm('Effacer la liste en cours ?')){localStorage.removeItem('iron-tide-v03');location.reload()}return}
 render();}
document.addEventListener('change',e=>{if(e.target.id==='import'){let file=e.target.files?.[0];if(!file)return;file.text().then(t=>{try{let o=JSON.parse(t),s=o.state||o;if(!Array.isArray(s.corps))throw Error('Format incompatible : corps manquants');state={...state,...s};render()}catch(err){alert('Import impossible : '+err.message)}});return}update(e)});
document.addEventListener('click',click);
try{let saved=localStorage.getItem('iron-tide-v03');if(saved){let s=JSON.parse(saved);if(Array.isArray(s.corps))state={...state,...s}}}catch(e){console.warn('Sauvegarde illisible',e)}
render();
